// Tests that reproduce `protocol/vectors.json` byte-for-byte.
//
// The vectors were generated by Tether's Swift implementation; the
// Android core passes the same vectors. This file mirrors
// `ProtocolTest.kt` (peripheral/central handshake, pairing code, G.711,
// OTP) in Dart.
import 'dart:convert' show jsonDecode;
import 'dart:io' show File;

import 'package:flutter_test/flutter_test.dart';
import 'package:sim_bridge/src/protocol/protocol.dart';

Map<String, dynamic> loadVectors() {
  final text = File('test/fixtures/vectors.json').readAsStringSync();
  return jsonDecode(text) as Map<String, dynamic>;
}

List<int> unhex(String hex) => hexDecode(hex);

Record single(List<int> bytes) {
  final reader = RecordReader()..append(bytes);
  final record = reader.next();
  expect(record, isNotNull);
  expect(reader.pendingBytes, 0);
  return record!;
}

P256KeyPair keyPair(Map<String, dynamic> h, String privKey, String pubKey) =>
    P256.keyPairFromScalar(unhex(h[privKey] as String),
        unhex(h[pubKey] as String));

void main() {
  late Map<String, dynamic> vectors;

  setUpAll(() {
    vectors = loadVectors();
    expect(vectors['version'], 1);
  });

  group('handshake vectors', () {
    test('peripheral matches Swift vectors (pair + resume)', () {
      final handshakes = vectors['handshakes'] as List;
      expect(handshakes.length, 2);
      for (final raw in handshakes) {
        final h = raw as Map<String, dynamic>;
        final sP = P256.keyPairFromScalar(
            unhex(h['s_P_priv'] as String), unhex(h['S_P'] as String));
        final eP = keyPair(h, 'e_P_priv', 'E_P');
        final token = (h['token'] as String).isNotEmpty
            ? unhex(h['token'] as String)
            : null;
        final p = PeripheralHandshake(sP,
            ephemeral: eP, nonce: unhex(h['n_P'] as String));

        final ack = p.receiveHello(
          single(unhex(h['hello_record'] as String)),
          pairedStaticKey: unhex(h['S_C'] as String),
          openToken: token,
        );
        expect(hexEncode(ack.encoded()), h['hello_ack_record']);
        expect(hexEncode(p.keys!.th), h['th']);
        expect(hexEncode(p.keys!.c2p), h['k_c2p']);
        expect(hexEncode(p.keys!.p2c), h['k_p2c']);

        final (session, fin) =
            p.receiveFinish(single(unhex(h['fin_c2p_record'] as String)));
        expect(hexEncode(fin.encoded()), h['fin_p2c_record']);

        final (channel, payload) =
            session.open(single(unhex(h['c2p_ctr1_record'] as String)));
        expect(
            hexEncode([channel, ...payload]), h['c2p_ctr1_plain']);
        final plain = unhex(h['p2c_ctr1_plain'] as String);
        final sealed =
            session.seal(plain[0], plain.sublist(1));
        expect(hexEncode(sealed.encoded()), h['p2c_ctr1_record']);
        expect(Message.parse(payload).t, 'ping');
      }
    });

    test('central matches Swift vectors (pair mode)', () {
      final h =
          (vectors['handshakes'] as List)[0] as Map<String, dynamic>;
      final sC = keyPair(h, 's_C_priv', 'S_C');
      final eC = keyPair(h, 'e_C_priv', 'E_C');
      final c = CentralHandshake(
        sC,
        unhex(h['S_P'] as String),
        token: unhex(h['token'] as String),
        ephemeral: eC,
        nonce: unhex(h['n_C'] as String),
      );
      expect(hexEncode(c.hello().encoded()), h['hello_record']);
      final (session, fin) =
          c.receive(single(unhex(h['hello_ack_record'] as String)));
      expect(hexEncode(fin.encoded()), h['fin_c2p_record']);
      c.verifyFinish(session, single(unhex(h['fin_p2c_record'] as String)));
      expect(hexEncode(P256.ecdh(eC, unhex(h['E_P'] as String))),
          h['dh1']);
    });

    test('peripheral rejects unknown device and closed pairing', () {
      final sP = P256.generate();
      final sC = P256.generate();

      // Resume with a static key the peripheral has never seen.
      final p = PeripheralHandshake(sP);
      final resume = CentralHandshake(sC, sP.publicEncoded);
      expect(
        p.receiveHello(resume.hello(),
            pairedStaticKey: P256.generate().publicEncoded),
        Record(RecordKind.reject, [RejectReason.unknownDevice]),
      );

      // Pair mode with no open token.
      final pair = CentralHandshake(
          sC, sP.publicEncoded, token: List<int>.filled(16, 0));
      expect(
        PeripheralHandshake(sP).receiveHello(pair.hello()),
        Record(RecordKind.reject, [RejectReason.pairingClosed]),
      );
    });

    test('wrong pairing token makes the finish fail', () {
      final sP = P256.generate();
      final sC = P256.generate();
      final p = PeripheralHandshake(sP);
      final c = CentralHandshake(sC, sP.publicEncoded,
          token: List<int>.filled(16, 1));
      final (session, fin) = c.receive(p.receiveHello(c.hello(),
          openToken: List<int>.filled(16, 2)));
      expect(() => p.receiveFinish(fin), throwsA(isA<SessionException>()));
      expect(session, isNotNull);
    });
  });

  group('loopback', () {
    test('50 messages, replay rejected, tamper rejected', () {
      final sP = P256.generate();
      final sC = P256.generate();
      final token = List<int>.filled(16, 7);
      final c = CentralHandshake(sC, sP.publicEncoded, token: token);
      final p = PeripheralHandshake(sP);
      final (cs, fin) =
          c.receive(p.receiveHello(c.hello(), openToken: token));
      final (ps, pfin) = p.receiveFinish(fin);
      c.verifyFinish(cs, pfin);

      for (var i = 0; i < 50; i++) {
        final record = cs.seal(0, 'm$i'.codeUnits);
        final (channel, payload) = ps.open(record);
        expect(channel, 0);
        expect(String.fromCharCodes(payload), 'm$i');
      }

      // Replay of an already-opened record: counter mismatch.
      final replayed = cs.seal(0, 'x'.codeUnits);
      ps.open(replayed);
      expect(
        () => ps.open(replayed),
        throwsA(isA<SessionException>().having(
            (e) => e.message, 'message', contains('counter'))),
      );

      // Flipped ciphertext bit: authentication failure.
      final tampered = cs.seal(0, 'y'.codeUnits);
      tampered.body[tampered.body.length - 1] ^= 1;
      expect(
        () => ps.open(tampered),
        throwsA(isA<SessionException>().having(
            (e) => e.message, 'message', 'auth failed')),
      );
    });
  });

  group('pairing code vector', () {
    test('parse, re-encode round-trip, malformed input', () {
      final pc = vectors['pairing_code'] as Map<String, dynamic>;
      final code = PairingCode.parse(pc['string'] as String)!;
      expect(hexEncode(code.peripheralKey), pc['S_P']);
      expect(hexEncode(code.token), pc['token']);
      expect(code.deviceName, pc['name']);
      expect(code.encode(), pc['string']);
      expect(PairingCode.parse('tether1:zz'), isNull);
      expect(PairingCode.parse('not-a-code'), isNull);
      expect(PairingCode.parse('tether1:AA.BB'), isNull);
    });
  });

  group('g711 vector', () {
    test('encode hex and decode round-trip', () {
      final g = vectors['g711'] as Map<String, dynamic>;
      final pcm = (g['pcm'] as List).cast<int>();
      expect(hexEncode(G711.encode(pcm)), g['ulaw']);
      final decoded = (g['decoded'] as List).cast<int>();
      expect(G711.decode(G711.encode(pcm)), decoded);
    });
  });

  group('otp vectors', () {
    test('extracts codes, including Persian digits', () {
      final otps = vectors['otp'] as List;
      expect(otps.length, 4);
      for (final raw in otps) {
        final o = raw as Map<String, dynamic>;
        expect(OtpExtractor.extract(o['text'] as String), o['code']);
      }
    });
  });
}
